{
  "qa": [
    {
      "question": "市场公关部的具体工作内容是什么？",
      "answer": "市场公关部负责挖掘有潜力的主播（如搞笑类、才艺类或能制作引发反思的段子的主播）并引入公司，同时负责与外部产品供应商（如化妆品公司）合作进行推荐。"
    },
    {
      "question": "上个月直播主打哪些产品？",
      "answer": "上个月直播主打年轻人相关产品，包括女生化妆品、服装以及男生的首饰和服装，其中女生产品占比更高，主要因节日送礼需求。"
    },
    {
      "question": "市场公关部对化妆品类产品的推广方案是什么？",
      "answer": "市场公关部负责与化妆品公司合作，通过挖掘有潜力的主播（如搞笑类、才艺类或能制作反思性内容的主播）进行产品推广。"
    }
  ]
}
